/// <summary>
/// extension class for <c>SalesConfirmJournalPost</c>
/// </summary>
[ExtensionOf(classStr(SalesConfirmJournalPost))]
final class METSalesConfirmJournalPost_Extension
{
}

Method.Source:
/// <summary>
/// CoC for postJournalPost method to update the ALM portal stage    
/// </summary>
public void postJournalPost()
{
    next postJournalPost();        

    if (salesTable)
    {
        METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);

        if (metSalesTable)
        {
            metSalesTable.skipBusinessEvents(true);               
            metSalesTable.ALMPortalStage = custConfirmJour.METALMPortalStage;

            // Bug 415418: CR- Check Sales order confirmations and Invoice Merging for multiple orders: Place orders for same customer through ALM Legacy Supplier Portal, Retailer Portal.
            if (metSalesTable.ConfimRequired)
            {
                metSalesTable.ConfimRequired = NoYes::No;
            }

            metSalesTable.update();
        }

        if (CustTable::find(salesTable.CustAccount).METASNRequired == NoYes::Yes)
        {
            this.metRunCCRCheckBatch(salesTable);
        }
    }
}

/// <summary>
/// Schedules the CCR check batch job for the given sales order.
/// </summary>
/// <param name = "_salesTable">The confirmed sales order.</param>
private void metRunCCRCheckBatch(SalesTable _salesTable)
{
    METCustomerASNProcessor     metCustomerASNProcessor = METCustomerASNProcessor::construct();
    metCustomerASNProcessor.processSalesOrder(_salesTable);
}
